CREATE SCHEMA IF NOT EXISTS trading_nova;
CREATE TABLE IF NOT EXISTS trading_nova.market_events(id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,source TEXT NOT NULL,symbol TEXT NOT NULL,event_type TEXT NOT NULL,event_time TIMESTAMPTZ NOT NULL,received_at TIMESTAMPTZ NOT NULL,payload JSONB NOT NULL);
CREATE TABLE IF NOT EXISTS trading_nova.strategies(id TEXT PRIMARY KEY,version TEXT NOT NULL,status TEXT NOT NULL,thesis JSONB NOT NULL,falsification JSONB NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS trading_nova.orders(id TEXT PRIMARY KEY,client_id TEXT UNIQUE NOT NULL,tier TEXT NOT NULL,status TEXT NOT NULL,payload JSONB NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS trading_nova.fills(id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES trading_nova.orders(id),qty NUMERIC NOT NULL,price NUMERIC NOT NULL,fee NUMERIC NOT NULL DEFAULT 0,filled_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS trading_nova.risk_configs(version TEXT PRIMARY KEY,config_hash TEXT NOT NULL,approved_by TEXT NOT NULL,approved_at TIMESTAMPTZ NOT NULL,payload JSONB NOT NULL);
CREATE TABLE IF NOT EXISTS trading_nova.journal_events(id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,event_hash TEXT UNIQUE NOT NULL,previous_hash TEXT,payload JSONB NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS trading_nova.audit_events(id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,event_type TEXT NOT NULL,actor TEXT NOT NULL,payload JSONB NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS trading_nova.idempotency_keys(key TEXT PRIMARY KEY,request_hash TEXT NOT NULL,result JSONB NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());